//! Client <-> server messages. Encoded as MessagePack (structs as maps,
//! `EntSnap` as a compact array). Snapshots and inputs travel in the compact
//! array forms of `wire.rs`. TypeScript types are generated by ts-rs into
//! `client/src/generated/` when `cargo test` runs.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::defs::attributes::{Attr, Attributes};
use crate::defs::items::{EquipSlot, Equipment, ItemId};
use crate::defs::loadout::{Loadout, Pick};
use crate::defs::trees::NodeId;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum ClassId {
    Wizard,
    Paladin,
    Barbarian,
    ElvenRanger,
}

impl ClassId {
    pub const ALL: [ClassId; 4] = [ClassId::Wizard, ClassId::Paladin, ClassId::Barbarian, ClassId::ElvenRanger];
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum BossId {
    Demon,
    Lich,
    Dragon,
}

impl BossId {
    pub const ALL: [BossId; 3] = [BossId::Demon, BossId::Lich, BossId::Dragon];
}

/// Which kind of level a run plays.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum LevelId {
    Dungeon,
}

/// A level and its options, as the lobby starts it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(tag = "level")]
#[ts(export)]
pub enum LevelChoice {
    /// `boss: None` = random end boss.
    Dungeon { boss: Option<BossId> },
}

/// One fixed simulation step (1/60 s) of player input.
#[derive(Debug, Clone, Default, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct InputMsg {
    pub seq: u32,
    /// Movement direction, each -1, 0 or 1.
    pub mx: i8,
    pub my: i8,
    /// Aim angle in radians and distance to the cursor in pixels.
    pub aim: f32,
    pub aim_dist: f32,
    /// Shot id when the client fired its primary/secondary on this step.
    pub primary: Option<u16>,
    pub secondary: Option<u16>,
    /// How far in the past the client sees the world (rtt/2 + interpolation delay), ms.
    pub view_lag: u16,
    /// Measured round trip time, ms (used to fast-forward the player's projectiles).
    pub rtt: u16,
    /// Use the nearest object in hand reach (E): push a barrel.
    #[serde(default)]
    pub act: bool,
}

#[derive(Debug, Clone, Deserialize, Serialize, TS)]
#[serde(tag = "t")]
#[ts(export)]
pub enum ClientMsg {
    /// Play as one of the account's characters (not while in a room). The
    /// server answers with `Character`.
    SelectCharacter { id: i32 },
    CreateRun { name: String },
    JoinRun { run_id: u32 },
    LeaveRun,
    SetReady { ready: bool },
    /// Host only, before the run starts. `None` = random end boss.
    SelectBoss { boss: Option<BossId> },
    /// Host only. Uses the room's chosen boss.
    StartRun,
    Input(InputMsg),
    Ping { time: f64 },
    Spectate { dir: i8 },
    /// Lobby or waiting room, not while ready: buy the next point of an Attribute with XP.
    BuyAttribute { attr: Attr },
    /// Buy a skill-tree node of your class with XP.
    BuyNode { node: NodeId },
    /// Give back all XP spent on the shop and the tree, for coins.
    Respec,
    /// Put an owned item in a slot (`None` = empty the slot).
    Equip { slot: EquipSlot, item: Option<ItemId> },
    /// Save the two abilities taken into the next run. Any pick that fits its slot is stored; what is
    /// wrong with it shows in `CharacterInfo.sheet.loadout_error` and stops Ready and Start.
    SetLoadout { primary: Pick, secondary: Pick },
    /// Debug: put a copy of an item in your inventory (for a debug account).
    DebugGrantItem { item: ItemId },
    /// Debug: set your hero's darkvision (0..=1 of its vision), in a debug run.
    DebugDarkvision { ratio: f32 },
    /// Debug: put an effect (EffectKind id) on your hero, in a debug run.
    DebugEffect { kind: u8 },
    /// Debug, waiting room: set any ability of your class in the two slots (for a debug account, in a debug room).
    DebugLoadout { primary: Pick, secondary: Pick },
    /// Debug, waiting room: put a weapon in your Melee or Ranged slot (`None` = an empty slot; for a debug account, in a debug room).
    DebugEquip { slot: EquipSlot, item: Option<ItemId> },
    /// Debug, in a debug run: immortal (the default) or mortal.
    DebugImmortal { on: bool },
    /// Debug, lobby or waiting room: `BuyAttribute` without the XP cost (for a debug account).
    DebugBuyAttribute { attr: Attr },
    /// Debug: `BuyNode` without the XP cost (for a debug account; the neighbour and Attribute checks stay).
    DebugBuyNode { node: NodeId },
    /// Debug: `Respec` without the coin cost (for a debug account).
    DebugRespec,
    /// In a run: the rules log on or off, and whether to send detail lines. Sent again on every run start.
    RulesLog { on: bool, details: bool },
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct RunSummary {
    pub id: u32,
    pub name: String,
    pub players: u8,
    pub max_players: u8,
    pub started: bool,
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct RoomPlayer {
    pub id: u32,
    pub name: String,
    pub class: ClassId,
    pub ready: bool,
    /// The two abilities that will play (the debug picks when set).
    pub loadout: Loadout,
    /// The Melee and Ranged weapons that will play.
    pub weapons: Vec<ItemId>,
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct PlayerInfo {
    /// Entity id inside the run.
    pub ent: u32,
    pub name: String,
    pub class: ClassId,
    /// The worn melee weapon (the class starter when the slot is empty) and the worn ranged one.
    pub melee: ItemId,
    pub ranged: Option<ItemId>,
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct RunStartInfo {
    /// The level type (decides how the client reads the map later).
    pub level: LevelId,
    pub width: u16,
    pub height: u16,
    /// One byte per tile, row-major. See `Tile` in dungeon/mod.rs.
    #[serde(with = "serde_bytes")]
    #[ts(type = "Uint8Array")]
    pub tiles: Vec<u8>,
    pub tile_size: u16,
    /// Entity id of the receiving player.
    pub you: u32,
    pub players: Vec<PlayerInfo>,
    pub spawn_x: f64,
    pub spawn_y: f64,
    /// The receiving hero's resolved move speed (px/s); prediction uses it as sent.
    pub speed: f64,
    /// Primary and secondary ability with their numbers resolved for the receiving hero.
    pub abilities: [crate::sheet::ResolvedAbility; 2],
    /// Strike with the melee weapon: what a ranged primary does in melee.
    pub fallback: crate::sheet::ResolvedAbility,
    /// Every static light (torches, lava) and its state.
    pub lights: Vec<LightInfo>,
    /// A debug run: every hero is in debug mode (badge, F4/F8/F9).
    pub debug: bool,
}

/// A static light at run start, as an array: `[id, kind, colour, x, y, on]`
/// (tile coordinates; colour 0xRRGGBB; kind = `LightKind` id).
#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct LightInfo(pub u32, pub u8, pub u32, pub u16, pub u16, pub bool);

/// A moving light near the viewer: `[x, y, kind, colour]` (px; colour `None` = the kind's default).
#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct MovingLight(pub f32, pub f32, pub u8, pub Option<u32>);

/// Compact entity state, serialized as an array:
/// `[id, kind, x, y, hp(0-255), anim, aim, anim_ms, flags, extra, effects]`.
/// `extra` for projectiles is `(owner_id << 16) | shot_id`.
/// `effects`: bitmask of `EffectKind` ids (creatures only).
#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct EntSnap(pub u32, pub u8, pub f32, pub f32, pub u8, pub u8, pub f32, pub u16, pub u8, pub u32, pub u16);

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct SelfState {
    pub alive: bool,
    pub hp: f32,
    pub max_hp: f32,
    /// Authoritative position and dash state for reconciliation.
    pub x: f64,
    pub y: f64,
    pub dash_t: f64,
    pub dash_dx: f64,
    pub dash_dy: f64,
    /// Knockback velocity (px/s), zero when not pushed.
    pub knock_vx: f64,
    pub knock_vy: f64,
    /// Remaining cooldowns (s).
    pub cd1: f32,
    pub cd2: f32,
    /// Entity id being spectated when dead.
    pub spectating: Option<u32>,
    /// The viewed hero's darkvision as a percentage of its vision, 0-100.
    pub darkvision: u8,
    /// The viewed hero's vision (tiles) through its effects (blind 0, asleep dimmed).
    pub vision: f32,
    /// The own hero's effects: (`EffectKind` id, seconds left).
    pub effects: Vec<(u8, f32)>,
    /// Factor on the own hero's move speed (0 while it cannot move); prediction uses it.
    pub speed_mul: f32,
    /// The own hero cannot act (asleep, stone): no predicted abilities.
    pub no_act: bool,
    /// Factor on the own hero's cooldowns: 0.8 while Berserker is active, else 1. Prediction multiplies by it.
    pub cd_mul: f32,
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct BossBar {
    pub kind: BossId,
    pub hp: f32,
    pub max_hp: f32,
    pub immune: bool,
    pub enraged: bool,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(tag = "t")]
#[ts(export)]
pub enum Ev {
    /// Damage number. `p` = the victim is a player. `ty`: the hit's main
    /// `DamageType` (colour); `imm`: fully resisted (shown as "immune").
    Dmg { x: f32, y: f32, v: f32, crit: bool, p: bool, ty: u8, imm: bool },
    /// `p`: on a hero (drawn under the darkness with the hero).
    Heal { x: f32, y: f32, v: f32, p: bool },
    /// Explosion / area effect. k: 0 fireball, 1 heal ring, 2 fire ring, 3 dark burst, 4 dragon fireball,
    /// 5 ogre ground slam (shockwave), 6 lich nova (dark purple burst), 7 barrel explosion, 8 chest smashed (splinters), 9 the wolf's green nature puff,
    /// 10 frost nova (icy ring), 11 war cry (red ring), 12 haste ring, 13 purify ring
    Boom { x: f32, y: f32, r: f32, k: u8 },
    Died { id: u32, x: f32, y: f32, kind: u8 },
    /// A minion appears. k: 0 raised skeleton (green), 1 summoned imp (fire), 2 raised by the lich (dark purple).
    Raise { x: f32, y: f32, k: u8 },
    Immune { x: f32, y: f32 },
    Tile { x: u16, y: u16, v: u8 },
    Msg { text: String },
    /// Coins found at a spot (chest or kill); every living party member gets `v`.
    Coins { x: f32, y: f32, v: u32 },
    /// A hero is lost to the terrain. how: 0 falls into a chasm, 1 drowns,
    /// 2 climbs back out onto safe ground (debug mode only).
    Sink { id: u32, x: f32, y: f32, how: u8 },
    /// A static light switched or recoloured; carries its current state.
    Light { id: u32, on: bool, colour: u32 },
    /// A static light created mid-run (tile coordinates).
    LightAdd { id: u32, kind: u8, colour: u32, x: u16, y: u16, on: bool },
    LightRemove { id: u32 },
    /// A status effect started (on) or ended on entity id; kind = EffectKind id, look = EffectLook id
    /// (0 when it ended).
    Effect { id: u32, kind: u8, on: bool, look: u8 },
    /// The wolf `id` growls at an enemy it detected (a sound: sent to the whole party, drawn above the darkness).
    Growl { id: u32 },
    /// Chain Spark jumps from (x, y) to (x2, y2); sent to the whole party like hero hits.
    Zap { x: f32, y: f32, x2: f32, y2: f32 },
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct Snapshot {
    pub tick: u32,
    /// Last processed input sequence of the receiving player.
    pub ack: u32,
    pub ents: Vec<EntSnap>,
    pub me: SelfState,
    pub boss: Option<BossBar>,
    pub ev: Vec<Ev>,
    /// Lich drain beams: the lich first, then every channelling disciple. Sent
    /// while the boss fight is on or any of them is in view, so the beams show
    /// even when an end is out of sight. `None` otherwise.
    pub drain: Option<Vec<(f32, f32)>>,
    /// Moving lights whose light can reach the viewer's sight.
    pub lights: Vec<MovingLight>,
    /// The non-default looks of the effects on the sent entities: (entity id, `EffectKind` id,
    /// `EffectLook` id).
    pub looks: Vec<(u32, u8, u8)>,
    /// Server simulation time spent per tick (ms, averaged).
    pub srv_ms: f32,
    /// The rules log, for a player who turned it on.
    pub log: Option<crate::run::rules_log::LogW>,
}

#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct PlayerStats {
    pub name: String,
    pub class: ClassId,
    pub kills: u32,
    pub damage: f32,
    pub healing: f32,
    pub xp: u32,
    pub coins: u32,
    pub alive: bool,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(tag = "t")]
#[ts(export)]
pub enum ServerMsg {
    Welcome { id: u32, debug: bool },
    Lobby { runs: Vec<RunSummary> },
    /// `level`: the level the run will play; `boss`: the host's choice of end boss for the dungeon, `None` = random.
    Room { run_id: u32, name: String, host: u32, players: Vec<RoomPlayer>, level: LevelId, boss: Option<BossId> },
    /// The receiving player's selected character and its progress.
    Character(CharacterInfo),
    RunStarted(RunStartInfo),
    Snap(Snapshot),
    /// `boss`: the level's end boss, if it has one.
    RunEnded { victory: bool, level: LevelId, boss: Option<BossId>, time: f32, stats: Vec<PlayerStats> },
    Pong { time: f64 },
    Error { msg: String },
    /// Debug mode: shortest walkable path from the player to the boss (pixel waypoints).
    /// `ogre`: the path to the ogre mini-boss while it lives (else empty). `immortal`: false after `DebugImmortal { on: false }`.
    DebugPath { on: bool, immortal: bool, points: Vec<(f32, f32)>, ogre: Vec<(f32, f32)> },
}

/// A character and its progress, as the client sees it (read only: the server
/// never accepts progress values from the client).
#[derive(Debug, Clone, Serialize, TS)]
#[ts(export)]
pub struct CharacterInfo {
    pub id: i32,
    pub name: String,
    pub class: ClassId,
    /// Unspent XP.
    pub xp: u32,
    /// All XP ever earned.
    pub total_xp: u32,
    /// Unspent coins (a respec costs coins).
    pub coins: u32,
    /// Attribute points bought in the shop.
    pub bought: Attributes,
    /// Owned skill-tree nodes (sorted, without the start node).
    pub nodes: Vec<NodeId>,
    pub equipment: Equipment,
    /// Owned items that are not worn (a worn item leaves the inventory).
    pub inventory: Vec<ItemId>,
    /// The saved abilities.
    pub loadout: Loadout,
    /// XP spent on the shop and the tree (refunded by a respec).
    pub xp_spent: u32,
    /// The coins a respec costs now.
    pub respec_price: u32,
    /// The XP price of the next point of each Attribute, in `Attr` order.
    pub prices: [u32; 6],
    /// The sheet numbers of the saved build.
    pub sheet: crate::sheet::SheetSummary,
}

pub fn encode(msg: &ServerMsg) -> Vec<u8> {
    rmp_serde::to_vec_named(msg).expect("encode server msg")
}

pub fn decode(bytes: &[u8]) -> Option<ClientMsg> {
    match bytes.first() {
        // A bare array is a compact input (see wire.rs).
        Some(0x90..=0x9f | 0xdc | 0xdd) => rmp_serde::from_slice::<crate::wire::InputW>(bytes).ok().map(|w| ClientMsg::Input(w.into())),
        _ => rmp_serde::from_slice(bytes).ok(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::defs::abilities::AbilityId;
    use crate::defs::items::EquipSlot;
    use crate::defs::loadout::Source;

    #[test]
    fn client_msg_roundtrip() {
        let m = ClientMsg::Input(InputMsg { seq: 7, mx: 1, my: -1, aim: 0.5, primary: Some(3), ..Default::default() });
        let bytes = rmp_serde::to_vec_named(&m).unwrap();
        match decode(&bytes) {
            Some(ClientMsg::Input(i)) => {
                assert_eq!(i.seq, 7);
                assert_eq!(i.primary, Some(3));
            }
            other => panic!("unexpected {other:?}"),
        }
        let select = rmp_serde::to_vec_named(&ClientMsg::SelectCharacter { id: 3 }).unwrap();
        assert!(matches!(decode(&select), Some(ClientMsg::SelectCharacter { id: 3 })));
        let json = r#"{"t":"DebugLoadout","primary":{"ability":"Strike","source":"Own"},"secondary":{"ability":"Charge","source":{"Item":"Ring1"}}}"#;
        let m: ClientMsg = serde_json::from_str(json).unwrap();
        let bytes = rmp_serde::to_vec_named(&m).unwrap();
        match decode(&bytes) {
            Some(ClientMsg::DebugLoadout { primary, secondary }) => {
                assert_eq!(primary, Pick { ability: AbilityId::Strike, source: Source::Own });
                assert_eq!(secondary, Pick { ability: AbilityId::Charge, source: Source::Item(EquipSlot::Ring1) });
            }
            other => panic!("unexpected {other:?}"),
        }
    }

    #[test]
    fn debug_equip_round_trips() {
        let json = r#"{"t":"DebugEquip","slot":"Ranged","item":"ThrowingAxes"}"#;
        let m: ClientMsg = serde_json::from_str(json).unwrap();
        let bytes = rmp_serde::to_vec_named(&m).unwrap();
        match decode(&bytes) {
            Some(ClientMsg::DebugEquip { slot, item }) => {
                assert_eq!(slot, EquipSlot::Ranged);
                assert_eq!(item, Some(ItemId::ThrowingAxes));
            }
            other => panic!("unexpected {other:?}"),
        }
        let none: ClientMsg = serde_json::from_str(r#"{"t":"DebugEquip","slot":"Ranged","item":null}"#).unwrap();
        assert!(matches!(none, ClientMsg::DebugEquip { item: None, .. }));
    }

    #[test]
    fn build_messages_round_trip() {
        use crate::defs::abilities::AbilityId;
        use crate::defs::attributes::Attr;
        use crate::defs::loadout::Source;
        let via = |json: &str| -> ClientMsg {
            let m: ClientMsg = serde_json::from_str(json).unwrap();
            decode(&rmp_serde::to_vec_named(&m).unwrap()).unwrap_or_else(|| panic!("{json} does not decode"))
        };
        assert!(matches!(via(r#"{"t":"BuyAttribute","attr":"Str"}"#), ClientMsg::BuyAttribute { attr: Attr::Str }));
        assert!(matches!(via(r#"{"t":"BuyNode","node":"WA2"}"#), ClientMsg::BuyNode { node: NodeId::WA2 }));
        assert!(matches!(via(r#"{"t":"Respec"}"#), ClientMsg::Respec));
        assert!(matches!(via(r#"{"t":"Equip","slot":"Melee","item":null}"#), ClientMsg::Equip { slot: EquipSlot::Melee, item: None }));
        assert!(matches!(via(r#"{"t":"Equip","slot":"Ring1","item":"RingOfInsight"}"#), ClientMsg::Equip { slot: EquipSlot::Ring1, item: Some(ItemId::RingOfInsight) }));
        assert!(matches!(via(r#"{"t":"DebugGrantItem","item":"WarHammer"}"#), ClientMsg::DebugGrantItem { item: ItemId::WarHammer }));
        let json = r#"{"t":"SetLoadout","primary":{"ability":"Strike","source":"Own"},"secondary":{"ability":"Charge","source":{"Item":"Ring1"}}}"#;
        match via(json) {
            ClientMsg::SetLoadout { primary, secondary } => {
                assert_eq!(primary, Pick { ability: AbilityId::Strike, source: Source::Own });
                assert_eq!(secondary, Pick { ability: AbilityId::Charge, source: Source::Item(EquipSlot::Ring1) });
            }
            other => panic!("unexpected {other:?}"),
        }
    }
}
